 static long Creation(IntPtr h){long c,e,k,u;Check(GetProcessTimes(h,out c,out e,out k,out u)&&c!=0,"Original creation query");return c;}
 static string Quote(string v){var b=new StringBuilder("\"");int n=0;foreach(char c in v){if(c=='\\'){n++;continue;}b.Append('\\',c=='"'?n*2+1:n);b.Append(c);n=0;}return b.Append('\\',n*2).Append('"').ToString();}
 public sealed class Child:IDisposable {
  public PI pin;public IntPtr output,error,control;public long creation;
  public void Dispose(){if(pin.process!=IntPtr.Zero){if(WaitForSingleObject(pin.process,0)!=0){Check(TerminateProcess(pin.process,74),"Owned failure terminate");Check(WaitForSingleObject(pin.process,5000)==0,"Owned failure reap");}CloseHandle(pin.process);pin.process=IntPtr.Zero;}if(pin.thread!=IntPtr.Zero)CloseHandle(pin.thread);if(control!=IntPtr.Zero)CloseHandle(control);if(output!=IntPtr.Zero)CloseHandle(output);if(error!=IntPtr.Zero)CloseHandle(error);}
 }
 public static Child Start(string exe,string[] args,string desktop,IntPtr job){
  var child=new Child();IntPtr ow=IntPtr.Zero,ew=IntPtr.Zero,input=IntPtr.Zero,attrs=IntPtr.Zero,handles=IntPtr.Zero;bool initialized=false;
  try{SA sa=new SA{size=Marshal.SizeOf(typeof(SA)),inherit=1};Check(CreatePipe(out child.output,out ow,ref sa,4096),"Owned stdout pipe");Check(CreatePipe(out child.error,out ew,ref sa,4096),"Owned stderr pipe");Check(SetHandleInformation(child.output,1,0)&&SetHandleInformation(child.error,1,0),"Parent-only read pipes");Check(CreatePipe(out input,out child.control,ref sa,4096),"Owned control pipe");Check(SetHandleInformation(child.control,1,0),"Parent-only control writer");IntPtr size=IntPtr.Zero;InitializeProcThreadAttributeList(IntPtr.Zero,1,0,ref size);Check(size.ToInt64()>0&&size.ToInt64()<65536,"Attribute bound");attrs=Marshal.AllocHGlobal(size);Check(InitializeProcThreadAttributeList(attrs,1,0,ref size),"Initialize allowlist");initialized=true;IntPtr[] list=new[]{input,ow,ew};handles=Marshal.AllocHGlobal(IntPtr.Size*list.Length);Marshal.Copy(list,0,handles,list.Length);Check(UpdateProcThreadAttribute(attrs,0,new IntPtr(0x20002),handles,new IntPtr(IntPtr.Size*list.Length),IntPtr.Zero,IntPtr.Zero),"Exact inherited allowlist");var si=new SIX();si.startup.cb=Marshal.SizeOf(typeof(SIX));si.startup.desktop=desktop;si.startup.flags=0x100;si.startup.input=input;si.startup.output=ow;si.startup.error=ew;si.attributes=attrs;var command=new StringBuilder(Quote(exe));foreach(string a in args)command.Append(' ').Append(Quote(a));Check(CreateProcessW(exe,command,IntPtr.Zero,IntPtr.Zero,true,0x08080004,IntPtr.Zero,Path.GetDirectoryName(exe),ref si,out child.pin),"Owned suspended fixture");Check(AssignProcessToJobObject(job,child.pin.process),"Owned observer Job binding");child.creation=Creation(child.pin.process);Check(ResumeThread(child.pin.thread)!=0xffffffff,"Resume fixture");return child;}catch{child.Dispose();throw;}finally{if(initialized)DeleteProcThreadAttributeList(attrs);if(attrs!=IntPtr.Zero)Marshal.FreeHGlobal(attrs);if(handles!=IntPtr.Zero)Marshal.FreeHGlobal(handles);foreach(IntPtr h in new[]{ow,ew,input})if(h!=IntPtr.Zero&&h!=new IntPtr(-1))CloseHandle(h);}
 }
 public static string Line(Child c,int seconds){var watch=Stopwatch.StartNew();var data=new List<byte>();var errors=new List<byte>();while(watch.Elapsed.TotalSeconds<seconds){foreach(var pair in new[]{new[]{c.output,new IntPtr(0)},new[]{c.error,new IntPtr(1)}}){uint available;if(!PeekNamedPipe(pair[0],IntPtr.Zero,0,IntPtr.Zero,out available,IntPtr.Zero)){Check(Marshal.GetLastWin32Error()==109,"Owned pipe query");continue;}if(available==0)continue;byte[] block=new byte[Math.Min(available,128u)];uint read;Check(ReadFile(pair[0],block,(uint)block.Length,out read,IntPtr.Zero),"Owned pipe read");var target=pair[1]==IntPtr.Zero?data:errors;for(int i=0;i<read;i++)target.Add(block[i]);Check(target.Count<=65536,"Handshake output bound");if(pair[1]==IntPtr.Zero&&data.Contains(10)){int end=data.IndexOf(10);Check(end==data.Count-1,"Unexpected queued stdout");return new UTF8Encoding(false,true).GetString(data.ToArray()).TrimEnd('\r','\n');}}if(WaitForSingleObject(c.pin.process,0)==0){uint remaining;bool queued=PeekNamedPipe(c.output,IntPtr.Zero,0,IntPtr.Zero,out remaining,IntPtr.Zero)&&remaining>0;if(!queued)queued=PeekNamedPipe(c.error,IntPtr.Zero,0,IntPtr.Zero,out remaining,IntPtr.Zero)&&remaining>0;Check(queued,"Fixture exited before handshake; stderr="+Encoding.UTF8.GetString(errors.ToArray()));}Thread.Sleep(10);}throw new Exception("Handshake deadline");}

