 public static bool Live(Child c){return WaitForSingleObject(c.pin.process,0)==258&&Creation(c.pin.process)==c.creation;}
 public static void Release(Child c){Check(Live(c),"Original holder live before release");uint n;Check(WriteFile(c.control,new byte[]{(byte)'R'},1,out n,IntPtr.Zero)&&n==1,"Exact bounded release byte");CloseHandle(c.control);c.control=IntPtr.Zero;}
 public static void SuccessfulExit(Child c){Check(WaitForSingleObject(c.pin.process,5000)==0,"Holder bounded exit");uint code;Check(GetExitCodeProcess(c.pin.process,out code)&&code==0,"Holder normal finish exit0");}
 public static void Absent(string path){Check(path.Length<248,"Collector long path unsupported");uint flags=GetFileAttributesW(path);int error=Marshal.GetLastWin32Error();Check(flags==0xffffffff&&(error==2||error==3),"Native original path absence proof");}
 public static void JournalDenied(string path,Dictionary<string,object> evidence){Check(path.Length<248,"Collector long path unsupported");SA sa=new SA{size=Marshal.SizeOf(typeof(SA))};IntPtr f=CreateFileW(path,0x80000000,7,ref sa,3,0x00200000,IntPtr.Zero);Check(f!=new IntPtr(-1)&&f!=IntPtr.Zero,"Original journal open");try{FileInfoNative info;Check(GetFileInformationByHandle(f,out info)&&(info.attributes&0x410)==0&&info.links==1,"Original journal metadata");FileIdInfo id;Check(GetFileInformationByHandleEx(f,18,out id,(uint)Marshal.SizeOf(typeof(FileIdInfo))),"Original journal 128-bit identity");var native=(Dictionary<string,object>)evidence["native_identity"];var expected=(Dictionary<string,object>)native["Windows"];Check(id.volume==Convert.ToUInt64(expected["volume_serial"]),"Original journal volume identity");int index=0;foreach(object item in (System.Collections.IEnumerable)expected["file_id"]){Check(index<16&&id.id[index++]==Convert.ToByte(item),"Original journal file identity");}Check(index==16&&(((ulong)info.high<<32)|info.low)==Convert.ToUInt64(evidence["bytes"]),"Original journal metadata bound");byte[] b=new byte[1];uint read;bool ok=ReadFile(f,b,1,out read,IntPtr.Zero);int error=Marshal.GetLastWin32Error();Check(!ok&&error==33,"Actual live journal lock denial");}finally{CloseHandle(f);}}

